<section class="space-y-3"><div class="flex flex-wrap items-center justify-between gap-2"><div><h2 class="font-semibold">Saved snapshots</h2><p class="text-xs opacity-65">A saved picture of the records available for that date. Later changes do not rewrite it.</p></div><button class="btn btn-primary" type="button" data-worth-snapshot>Save snapshot</button></div><div class="overflow-x-auto rounded-sm border border-base-300 bg-base-100"><table class="table table-sm"><thead><tr><th>Date</th><th>Assets</th><th>Debts</th><th>Net worth</th><th>Details</th><th>Actions</th></tr></thead><tbody>@forelse($snapshots->reverse() as $snapshot)<tr><td class="whitespace-nowrap">{{ $snapshot->date->format('d M Y') }}</td><td class="whitespace-nowrap">{{ $money($snapshot->assets_cents) }}</td><td class="whitespace-nowrap">{{ $money($snapshot->debts_cents) }}</td><td class="whitespace-nowrap font-semibold">{{ $money($snapshot->net_worth_cents) }}</td><td><details class="text-xs"><summary class="cursor-pointer">View breakdown</summary><div class="mt-2 min-w-48 space-y-1">@foreach($snapshot->details['assets'] ?? [] as $item)<p>{{ $item['name'] }}: {{ $money($item['amount']) }} &middot; valued {{ $item['date'] }}</p>@endforeach @foreach($snapshot->details['debts'] ?? [] as $item)<p>{{ $item['name'] }} (debt): {{ $money($item['amount']) }}</p>@endforeach @if(($snapshot->details['excluded'] ?? 0) > 0)<p class="text-warning">{{ $snapshot->details['excluded'] }} currently tracked items had no recorded value by this date and were excluded.</p>@endif @if(($snapshot->details['stale'] ?? 0) > 0)<p class="text-warning">{{ $snapshot->details['stale'] }} valuations were more than 30 days old.</p>@endif</div></details></td><td><form method="post" action="{{ route('net-worth.snapshots.destroy', $snapshot) }}" data-confirm="Remove this snapshot from your trend? Current assets and debts will be kept. You can restore the snapshot." data-confirm-title="Remove snapshot?" data-confirm-label="Remove">@csrf @method('DELETE')<button class="btn btn-xs btn-ghost text-error">Remove</button></form></td></tr>@empty<tr><td colspan="6" class="p-6 text-center opacity-65">Save your first snapshot to start tracking changes over time.</td></tr>@endforelse</tbody></table></div></section>
